+}
+.masthead nav a {
+  padding: 0.55rem 1rem;
+  border: 1px solid transparent;
+  border-radius: 7px;
+  font-size: 0.825rem;
+  font-weight: 550;
+  text-decoration: none;
+  color: var(--ink-2);
+  white-space: nowrap;
+}
+.masthead nav a:hover {
+  color: var(--ink);
+  background: var(--surface);
+}
+.masthead nav a[aria-current="page"] {
+  color: var(--accent);
+  background: var(--surface);
+  border-color: var(--line);
+  box-shadow: 0 1px 3px rgb(0 0 0 / 5%);
