+} from "../data.js";
+import {
+  coverageBar,
+  el,
+  levelBar,
+  levelLegend,
+  palette,
+  trackBand,
+} from "../ui.js";
+import { go, targetHref, targetPath } from "../route.js";
+
+const REPO =
